/* Reset */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
  padding: 50px 20px;
}

.pricing-container {
  max-width: 1050px;
  margin: 0 auto;
}

.section-title {
  text-align: center;
  margin-bottom: 45px;
}

.section-title h2 {
  font-size: 2rem;
  color: #0f172a;
  margin-bottom: 8px;
}

.section-title p {
  color: #64748b;
  font-size: 1rem;
}

/* Pricing Grid */
.pricing-grid {
  display: flex;
  justify-content: center;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 24px;
}

/* Pricing Card */
.pricing-card {
  flex: 1 1 300px;
  max-width: 330px;
  background-color: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
  transition: transform 0.25s, box-shadow 0.25s;
}

.pricing-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 15px 25px -5px rgba(0, 0, 0, 0.08);
}

/* Featured Card dengan Shadow Lebih Dalam & Border Aksen */
.pricing-card.featured {
  border: 2px solid #2563eb;
  box-shadow: 0 10px 25px -5px rgba(37, 99, 235, 0.15);
  transform: scale(1.03);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-6px);
  box-shadow: 0 20px 35px -5px rgba(37, 99, 235, 0.2);
}

/* Badge dengan Position: Absolute */
.ribbon-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background-color: #2563eb;
  color: #ffffff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 20px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  box-shadow: 0 2px 4px rgba(37, 99, 235, 0.3);
}

.plan-name {
  font-size: 1.3rem;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 6px;
}

.plan-desc {
  font-size: 0.85rem;
  color: #64748b;
  margin-bottom: 24px;
  min-height: 40px;
}

.price {
  margin-bottom: 24px;
  display: flex;
  align-items: baseline;
}

.currency {
  font-size: 1.1rem;
  font-weight: 600;
  color: #0f172a;
}

.amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: #0f172a;
  margin: 0 4px;
}

.period {
  font-size: 0.85rem;
  color: #64748b;
}

/* Fitur List */
.features {
  list-style: none;
  margin-bottom: 30px;
  flex-grow: 1;
}

.features li {
  font-size: 0.875rem;
  color: #475569;
  padding: 8px 0;
  border-bottom: 1px solid #f1f5f9;
  display: flex;
  align-items: center;
}

.features li::before {
  content: "✓";
  color: #22c55e;
  font-weight: 800;
  margin-right: 10px;
}

/* Tombol Kartu */
.btn-card {
  width: 100%;
  padding: 12px;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  background-color: #f8fafc;
  border: 1px solid #cbd5e1;
  color: #334155;
  transition: all 0.2s;
}

.btn-card:hover {
  background-color: #f1f5f9;
  border-color: #94a3b8;
}

.btn-featured {
  background-color: #2563eb;
  border-color: #2563eb;
  color: #ffffff;
}

.btn-featured:hover {
  background-color: #1d4ed8;
  border-color: #1d4ed8;
}
